From 13e2d5187f6b965ba3556caedb914baf81b98ed2 Mon Sep 17 00:00:00 2001
From: Dan Carpenter <dan.carpenter@oracle.com>
Date: Fri, 17 Mar 2017 23:52:35 +0300
Subject: [PATCH] bna: integer overflow bug in debugfs

We could allocate less memory than intended because we do:

	bnad->regdata = kzalloc(len << 2, GFP_KERNEL);

The shift can overflow leading to a crash.  This is debugfs code so the
impact is very small.

Fixes: 7afc5dbde091 ("bna: Add debugfs interface.")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Acked-by: Rasesh Mody <rasesh.mody@cavium.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

diff --git a/drivers/net/ethernet/brocade/bna/bnad_debugfs.c b/drivers/net/ethernet/brocade/bna/bnad_debugfs.c
index 05c1c1dd7751..cebfe3bd086e 100644
--- a/drivers/net/ethernet/brocade/bna/bnad_debugfs.c
+++ b/drivers/net/ethernet/brocade/bna/bnad_debugfs.c
@@ -325,7 +325,7 @@ bnad_debugfs_write_regrd(struct file *file, const char __user *buf,
 		return PTR_ERR(kern_buf);

 	rc = sscanf(kern_buf, "%x:%x", &addr, &len);
-	if (rc < 2) {
+	if (rc < 2 || len > UINT_MAX >> 2) {
 		netdev_warn(bnad->netdev, "failed to read user buffer\n");
 		kfree(kern_buf);
 		return -EINVAL;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug is caused by the potential for an integer overflow when calculating the memory allocation size for `bnad->regdata` using the expression `len << 2`. If `len` is sufficiently large, the left shift operation can exceed the maximum value representable by an integer, leading to an incorrect memory allocation size and potentially causing a crash. The added check ensures that `len` is within a safe range to prevent this overflow.

        Commit message:
        bna: integer overflow bug in debugfs

We could allocate less memory than intended because we do:

	bnad->regdata = kzalloc(len << 2, GFP_KERNEL);

The shift can overflow leading to a crash.  This is debugfs code so the
impact is very small.

Fixes: 7afc5dbde091 ("bna: Add debugfs interface.")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Acked-by: Rasesh Mody <rasesh.mody@cavium.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 static ssize_t
 bnad_debugfs_write_regrd(struct file *file, const char __user *buf,
 		size_t nbytes, loff_t *ppos)
 {
 	struct bnad_debug_info *regrd_debug = file->private_data;
 	struct bnad *bnad = (struct bnad *)regrd_debug->i_private;
 	struct bfa_ioc *ioc = &bnad->bna.ioceth.ioc;
 	int rc, i;
 	u32 addr, len;
 	u32 *regbuf;
 	void __iomem *rb, *reg_addr;
 	unsigned long flags;
 	void *kern_buf;

 	/* Copy the user space buf */
 	kern_buf = memdup_user(buf, nbytes);
 	if (IS_ERR(kern_buf))
 		return PTR_ERR(kern_buf);

 	rc = sscanf(kern_buf, "%x:%x", &addr, &len);
-	if (rc < 2) {
+	if (rc < 2 || len > UINT_MAX >> 2) {
 		netdev_warn(bnad->netdev, "failed to read user buffer\n");
 		kfree(kern_buf);
 		return -EINVAL;
 	}

 	kfree(kern_buf);
 	kfree(bnad->regdata);
 	bnad->reglen = 0;

 	bnad->regdata = kzalloc(len << 2, GFP_KERNEL);
 	if (!bnad->regdata)
 		return -ENOMEM;

 	bnad->reglen = len << 2;
 	rb = bfa_ioc_bar0(ioc);
 	addr &= BFA_REG_ADDRMSK(ioc);

 	/* offset and len sanity check */
 	rc = bna_reg_offset_check(ioc, addr, len);
 	if (rc) {
 		netdev_warn(bnad->netdev, "failed reg offset check\n");
 		kfree(bnad->regdata);
 		bnad->regdata = NULL;
 		bnad->reglen = 0;
 		return -EINVAL;
 	}

 	reg_addr = rb + addr;
 	regbuf =  (u32 *)bnad->regdata;
 	spin_lock_irqsave(&bnad->bna_lock, flags);
 	for (i = 0; i < len; i++) {
 		*regbuf = readl(reg_addr);
 		regbuf++;
 		reg_addr += sizeof(u32);
 	}
 	spin_unlock_irqrestore(&bnad->bna_lock, flags);

 	return nbytes;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
```c
-	if (rc < 2) {
+	if (rc < 2 || len > UINT_MAX >> 2) {
	bnad->regdata = kzalloc(len << 2, GFP_KERNEL);
	bnad->reglen = len << 2;
```

